// Programmatically starting and stopping Java Flight Recorder (JFR) inside a running application
import jdk.jfr.Recording;

public class DiagnosticRunner {
    public static void main(String[] args) throws Exception {
        Recording recording = new Recording();
        recording.setName("ProductionHotspotAudit");

        // Enable specific settings or custom profiles
        // recording.setToDisk(true);

        System.out.println("Starting JFR recording...");
        recording.start();

        // Simulate heavy workload
        Thread.sleep(30000);

        recording.stop();
        java.nio.file.Path path = java.nio.file.Paths.get("recording.jfr");
        recording.dump(path);
        recording.close();

        System.out.println("JFR recording saved to: " + path.toAbsolutePath());
    }
}
